#include "encore/field_psi.hpp"
namespace encore::upstream {
bool FieldTelepathyRuntime::initialize(const FieldPsiData*d,FieldTelepathyHost h){if(!d||!d->valid()||!h.player_has_field_skill||!h.probe||!h.admit_dialogue||!h.admit_target||!h.clear_event_collider||!h.turn||!h.effect||!h.target_telepathy||!h.dialogue||!h.press_prompt)return false;data_=d;host_=std::move(h);return true;}
bool FieldTelepathyRuntime::plan(FieldTelepathyProbe&p,bool&allowed,uint32_t&target,uint32_t&fallback,bool&prompt,std::string&e){target=fallback=0;prompt=false;if(!allowed){fallback=1;return host_.admit_dialogue(data_->fallback(fallback),e);}if(!host_.probe(p,e))return false;if(!p.collider){if(p.parent||p.parent_method||p.collider_method||p.has_thoughts||p.no_problem_thoughts||p.button_prompt){e="Telepathy null collider probe inconsistent";return false;}fallback=2;}else{if(p.parent_method&&!p.parent){e="Telepathy parent method without live source parent";return false;}target=p.parent_method?p.parent:p.collider_method?p.collider:0;if(target){if(p.has_thoughts){prompt=p.button_prompt;return host_.admit_target(target,e);}if(target==p.collider)fallback=3;else{fallback=p.no_problem_thoughts?3:4;prompt=!p.no_problem_thoughts&&p.button_prompt;}}else{fallback=3;prompt=p.button_prompt;}}return host_.admit_dialogue(data_->fallback(fallback),e);}
bool FieldTelepathyRuntime::admit(std::string&e){if(!data_){e="Telepathy source runtime absent";return false;}FieldTelepathyProbe p;bool allowed=false,prompt=false;uint32_t target=0,fallback=0;if(!host_.player_has_field_skill(allowed,e))return false;return plan(p,allowed,target,fallback,prompt,e);}
bool FieldTelepathyRuntime::execute(std::string&e){if(!data_){e="Telepathy source runtime absent";return false;}bool allowed=false;if(!host_.player_has_field_skill(allowed,e))return false;if(!allowed)return host_.dialogue(data_->fallback(1),e);if(!host_.clear_event_collider(e))return false;FieldTelepathyProbe p;bool prompt=false;uint32_t target=0,fallback=0;if(!plan(p,allowed,target,fallback,prompt,e))return false;if(target){if(!host_.turn(target,e))return false;if(p.has_thoughts){if(target!=p.collider&&!host_.effect(target,data_->effect(),e))return false;if(!host_.target_telepathy(target,e))return false;}else if(!host_.dialogue(data_->fallback(fallback),e))return false;}else if(!host_.dialogue(data_->fallback(fallback),e))return false;if(prompt&&!host_.press_prompt(p.collider,e))return false;e.clear();return true;}
}
